import torch
import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

KERNEL_NAME = "max_reduce_kernel"

PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.visible .entry max_reduce_kernel(
    .param .u64 X_ptr,
    .param .u64 Y_ptr,
    .param .u64 outer_p,
    .param .u64 reduce_p,
    .param .u64 inner_p
)
{
    .reg .pred %p<8>;
    .reg .f32 %f<8>;
    .reg .b32 %r<8>;
    .reg .b64 %rd<40>;

    ld.param.u64 %rd1, [X_ptr];
    ld.param.u64 %rd2, [Y_ptr];
    ld.param.u64 %rd3, [outer_p];
    ld.param.u64 %rd4, [reduce_p];
    ld.param.u64 %rd5, [inner_p];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;

    // total = outer * inner  (flattened output element count)
    mul.lo.s64 %rd6, %rd3, %rd5;

    // idx = blockIdx.x * blockDim.x + threadIdx.x
    mov.u32 %r1, %ctaid.x;
    mov.u32 %r2, %ntid.x;
    mul.wide.u32 %rd7, %r1, %r2;
    mov.u32 %r3, %tid.x;
    cvt.u64.u32 %rd8, %r3;
    add.s64 %rd9, %rd7, %rd8;

    // stride = gridDim.x * blockDim.x
    mov.u32 %r4, %nctaid.x;
    mul.wide.u32 %rd10, %r4, %r2;

LOOP_OUTER:
    setp.ge.u64 %p1, %rd9, %rd6;
    @%p1 bra DONE;

    // o = idx / inner ; i = idx - o * inner
    div.u64 %rd11, %rd9, %rd5;
    mul.lo.s64 %rd12, %rd11, %rd5;
    sub.s64 %rd13, %rd9, %rd12;

    // base = o * reduce * inner
    mul.lo.s64 %rd14, %rd11, %rd4;
    mul.lo.s64 %rd15, %rd14, %rd5;

    // idx0 = base + i
    add.s64 %rd16, %rd15, %rd13;
    shl.b64 %rd17, %rd16, 2;
    add.s64 %rd18, %rd1, %rd17;
    ld.global.f32 %f1, [%rd18];

    mov.u64 %rd19, 1;

LOOP_INNER:
    setp.ge.u64 %p2, %rd19, %rd4;
    @%p2 bra STORE;

    mul.lo.s64 %rd20, %rd19, %rd5;
    add.s64 %rd21, %rd15, %rd20;
    add.s64 %rd22, %rd21, %rd13;
    shl.b64 %rd23, %rd22, 2;
    add.s64 %rd24, %rd1, %rd23;
    ld.global.f32 %f2, [%rd24];

    setp.gt.f32 %p3, %f2, %f1;
    selp.f32 %f1, %f2, %f1, %p3;

    add.s64 %rd19, %rd19, 1;
    bra LOOP_INNER;

STORE:
    mul.lo.s64 %rd25, %rd11, %rd5;
    add.s64 %rd26, %rd25, %rd13;
    shl.b64 %rd27, %rd26, 2;
    add.s64 %rd28, %rd2, %rd27;
    st.global.f32 [%rd28], %f1;

    add.s64 %rd9, %rd9, %rd10;
    bra LOOP_OUTER;

