        y = torch.empty(out_sizes, device=x_c.device, dtype=x_c.dtype)

        threads = 256
        total = outer * inner
        max_blocks = (total + threads - 1) // threads

        # Target GPU (RTX 4090, sm_89) has 128 SMs. The measured occupancy
        # limiter for this kernel (256 threads/block, 33 regs/thread) is the
        # per-SM thread-count cap, which yields 6 resident blocks/SM (100%
        # theoretical occupancy). Size the grid to an exact whole number of
        # full waves (num_sm * blocks_per_sm) so there is no trailing partial
        # wave; the grid-stride loop inside the kernel still covers any
        # remaining output elements beyond the launched grid.
        num_sm = 128
        blocks_per_sm = 6
        grid_x = min(max_blocks, num_sm * blocks_per_sm)
        grid_x = max(grid_x, 1)

        stream = torch.cuda.current_stream()

        kernel_args = (
            u64(x_c.data_ptr()),
            u64(y.data_ptr()),
            u64(outer),
            u64(reduce),
            u64(inner),
        )
        self._module.launch(
            KERNEL_NAME,
            (int(grid_x), 1, 1),
            (int(threads), 1, 1),
            kernel_args,
            stream=stream,
        )

        return y

