    int64_t o = blockIdx.y;
    int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    if (o >= outer || i >= inner) return;

    // View this outer-slice as a (reduce, inner) matrix with row-major strides
