    T maxval = mX(0, i);
    #pragma unroll 4
    for (int64_t r = 1; r < reduce; ++r) {
        T v = mX(r, i);
        maxval = v > maxval ? v : maxval;
    }

    Y[o * inner + i] = maxval;
